# The ladder applied to "disk fills, page fires, engineer runs cleanup":
#   1. Eliminate  - fix the log retention bug that fills the disk
#   2. Reduce     - ticket at 70% instead of paging at 95%
#   3. Self-serve - one idempotent command anyone on call can run
#   4. Automate   - schedule it, rate-limit it, log every run
cleanup_old_logs() {
  local dir=$1 keep_days=${2:-7}
  find "$dir" -type f -name '*.log.gz' -mtime "+$keep_days" -print -delete
}

import time

TIERS = {"checkout": 0, "search": 1, "recommendations": 2, "prefetch": 3}

def admit(req, inflight, limit):
    # 1. Never spend CPU on work whose deadline already passed.
    if req.deadline_unix <= time.time():
        return False, "deadline expired before admission"

    # 2. Shed by criticality as concurrency fills up.
    #    ~50% full: prefetch dropped. ~80% full: only checkout served.
    headroom = 1 - (inflight / limit)
    if TIERS[req.tier] > headroom * len(TIERS):
        return False, "shed: tier too low for current load"

    return True, "admit"

import random

BASE, CAP = 0.1, 20.0     # seconds

def full_jitter_delay(attempt):
    # random over [0, capped exponential). The randomness is the point:
    # it de-synchronises clients that all failed at the same moment.
    return random.uniform(0, min(CAP, BASE * (2 ** attempt)))

RETRYABLE = {429, 500, 502, 503, 504}

def should_retry(status, method, has_idempotency_key, budget):
    if method not in ("GET", "HEAD", "PUT", "DELETE") and not has_idempotency_key:
        return False              # a retry could charge the card twice
    if status not in RETRYABLE:
        return False              # deterministic failure: retrying cannot help
    return budget.try_consume()   # token bucket: retries <= ~10% of successes

# Breaker: CLOSED --failure ratio too high--> OPEN --cooldown--> HALF_OPEN
#          HALF_OPEN --trial ok--> CLOSED   |   --trial fails--> OPEN
